  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "fulfillment" TEXT NOT NULL,
  "queue" TEXT NOT NULL,
  "task" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, fulfillment) REFERENCES fulfillment (tenant, id)
);

CREATE TABLE identifier (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "identifier_set" TEXT NOT NULL,
  "namespace" TEXT NOT NULL,
  "issuer" TEXT,
  "issuer_scope" TEXT NOT NULL,
  "value_" TEXT NOT NULL,
  "valid_from" TEXT NOT NULL,
  "valid_until" TEXT,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, identifier_set) REFERENCES identifier_set (tenant, id),
  FOREIGN KEY (tenant, issuer) REFERENCES issuer (tenant, id)
);

CREATE TABLE identifier_disposition (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "identifier" TEXT NOT NULL,
  "replacement" TEXT,
  "effective_at" TEXT NOT NULL,
  "reason" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, identifier) REFERENCES identifier (tenant, id),
  FOREIGN KEY (tenant, replacement) REFERENCES identifier (tenant, id)
);

CREATE TABLE identifier_set (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "label" TEXT NOT NULL,
  PRIMARY KEY (tenant, id)
);

CREATE TABLE issuer (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "key_" TEXT NOT NULL,
  PRIMARY KEY (tenant, id)
);

CREATE TABLE account (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "book" TEXT NOT NULL,
  "key_" TEXT NOT NULL,
  "unit" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, book) REFERENCES ledger_book (tenant, id)
);

CREATE TABLE entry (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "book" TEXT NOT NULL,
  "account" TEXT NOT NULL,
  "quantity" INTEGER NOT NULL,
  "next" TEXT,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, book) REFERENCES ledger_book (tenant, id),
  FOREIGN KEY (tenant, account) REFERENCES account (tenant, id),
  FOREIGN KEY (tenant, next) REFERENCES entry (tenant, id)
);

CREATE TABLE ledger_book (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "key_" TEXT NOT NULL,
  PRIMARY KEY (tenant, id)
);

CREATE TABLE posting_group (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "book" TEXT NOT NULL,
  "key_" TEXT NOT NULL,
  "claim" TEXT NOT NULL,
  "head" TEXT NOT NULL,
  "policy" TEXT NOT NULL,
  "reversal_of" TEXT,
  "reason" TEXT NOT NULL,
  "created_at" TEXT NOT NULL,
  "updated_at" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, book) REFERENCES ledger_book (tenant, id),
  FOREIGN KEY (tenant, head) REFERENCES entry (tenant, id),
  FOREIGN KEY (tenant, reversal_of) REFERENCES posting_group (tenant, id)
);

CREATE TABLE participation (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "participation_set" TEXT NOT NULL,
  "participant" TEXT NOT NULL,
  "role" TEXT NOT NULL,
  "valid_from" TEXT NOT NULL,
  "valid_until" TEXT,
  "recorded_by" TEXT NOT NULL,
  "reason" TEXT NOT NULL,
  "created_at" TEXT NOT NULL,
  "updated_at" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, participation_set) REFERENCES participation_set (tenant, id),
  FOREIGN KEY (tenant, participant) REFERENCES party (tenant, id),
  FOREIGN KEY (tenant, role) REFERENCES participation_role (tenant, id)
);

CREATE TABLE participation_end (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "participation" TEXT NOT NULL,
  "effective_at" TEXT NOT NULL,
  "revoked" INTEGER NOT NULL,
  "recorded_by" TEXT NOT NULL,
  "reason" TEXT NOT NULL,
  "created_at" TEXT NOT NULL,
  "updated_at" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, participation) REFERENCES participation (tenant, id)
);

CREATE TABLE participation_role (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "namespace" TEXT NOT NULL,
  "name" TEXT NOT NULL,
  "created_at" TEXT NOT NULL,
  "updated_at" TEXT NOT NULL,
  PRIMARY KEY (tenant, id)
);

CREATE TABLE participation_set (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "label" TEXT NOT NULL,
  "created_at" TEXT NOT NULL,
  "updated_at" TEXT NOT NULL,
  PRIMARY KEY (tenant, id)
);

CREATE TABLE party (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "label" TEXT NOT NULL,
  "identifiers" TEXT,
  "created_at" TEXT NOT NULL,
  "updated_at" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, identifiers) REFERENCES identifier_set (tenant, id)
);

CREATE TABLE principal_representation (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "party" TEXT NOT NULL,
  "principal" TEXT NOT NULL,
  "valid_from" TEXT NOT NULL,
  "valid_until" TEXT,
  "recorded_by" TEXT NOT NULL,
  "reason" TEXT NOT NULL,
  "created_at" TEXT NOT NULL,
  "updated_at" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, party) REFERENCES party (tenant, id)
);

CREATE TABLE representation_revocation (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "representation" TEXT NOT NULL,
  "effective_at" TEXT NOT NULL,
  "recorded_by" TEXT NOT NULL,
  "reason" TEXT NOT NULL,
  "created_at" TEXT NOT NULL,
  "updated_at" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, representation) REFERENCES principal_representation (tenant, id)
);

CREATE TABLE realization (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "pin" TEXT NOT NULL,
  "build_hash" TEXT NOT NULL,
  "manifest_digest" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, pin) REFERENCES specification_pin (tenant, id)
);

CREATE TABLE repository (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "key_" TEXT NOT NULL,
  "provider" TEXT NOT NULL,
  "locator" TEXT NOT NULL,
  "version" INTEGER NOT NULL,
  PRIMARY KEY (tenant, id)
);

CREATE TABLE specification_pin (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "repository" TEXT NOT NULL,
  "anchor" TEXT NOT NULL,
  "revision" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, repository) REFERENCES repository (tenant, id)
);

